/// Where a conversation is in its life: archived, in the trash and until
/// when, on hold, and what the retention rule is.
async fn conversation_lifecycle(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> axum::response::Response {
    if !find_session_in_cwd(&state.core, &id) {
        return StatusCode::NOT_FOUND.into_response();
    }
    let core = state.core.clone();
    let read = tokio::task::spawn_blocking(move || {
        let lifecycle = vak_core::trash::state(&core.shared_scope(), &id).unwrap_or_default();
        let window = vak_core::lifecycle::trash_window();
        serde_json::json!({
            "archived": lifecycle.archived,
            "trashed_at": lifecycle.trashed_at,
            "erase_on": lifecycle.trashed_at.map(|at| at + window),
            "held": core.conversation_held(&id),
            "trash_days": window.num_days(),
        })
    })
    .await;
    match read {
        Ok(lifecycle) => Json(lifecycle).into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

async fn delete_all_archived(State(state): State<AppState>) -> axum::response::Response {
    let archive = read_archive(&state.core);
    let local_archived: Vec<String> = archive
        .into_iter()
        .filter(|(id, archived)| *archived && find_session_in_cwd(&state.core, id))
        .map(|(id, _)| id)
        .collect();
    let running_archived = local_archived.iter().any(|id| {
        state.get(id).is_some_and(|handle| {
            handle
                .session
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_none()
        })
    });
    if running_archived {
        return (
            StatusCode::CONFLICT,
            Json(serde_json::json!({ "error": "stop running archived tasks before deleting all" })),
        )
            .into_response();
    }
    let home = state.core.shared_scope().into_root();
    let already = vak_core::trash::trashed(&vak_config::scope::SharedScope::new(&home));
    let newly: Vec<String> = local_archived
        .into_iter()
        .filter(|id| !already.contains(id))
        .collect();
    if let Err(error) =
        vak_core::trash::set(&vak_config::scope::SharedScope::new(&home), &newly, true)
    {
        return trash_write_failed(&error);
    }
    for id in &newly {
        state.forget_session(id);
        state.core.forget_spend_gate(id);
    }
    Json(serde_json::json!({ "trashed": newly.len() })).into_response()
}

async fn list_skills(
    State(state): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<AgentScopeQuery>,
) -> axum::response::Response {
    use axum::response::IntoResponse;
    let core = scoped_core!(&state, None, q.agent.as_deref());
    // `path` and `scope` tell the reader WHERE a skill came from. Discovery
    // reads two roots (`<cwd>/.vak/skills` then the Shared
    // `~/vak-home/.vak/skills` root), and a workspace skill is a very different
    // trust proposition from a Shared skill
    // one -- the admin console groups by this.
    let workspace_root = vak_config::scope::WorkspaceScope::new(core.cwd()).skills();
    let shared_root =
        vak_config::scope::WorkspaceScope::new(vak_config::paths::default_workspace()).skills();
    let skills: Vec<serde_json::Value> = core
        .skills_with_shadowed()
        .iter()
        .map(|s| {
            let scope = if s.path.starts_with(&shared_root) {
                "user"
            } else if s.path.starts_with(&workspace_root) {
                "workspace"
            } else {
                "user"
            };
            serde_json::json!({
                "name": s.name,
                "description": s.description,
                "path": s.path.display().to_string(),
                "scope": scope,
                "provenance": s.provenance,
                "shadowed": s.shadowed,
            })
        })
        .collect();
    Json(serde_json::json!({ "skills": skills })).into_response()
}

async fn list_commands(
    State(state): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<AgentScopeQuery>,
) -> axum::response::Response {
    use axum::response::IntoResponse;
    let core = scoped_core!(&state, None, q.agent.as_deref());
    Json(
        serde_json::json!({ "commands": core.custom_commands().into_iter().map(|command| serde_json::json!({
        "name": command.name, "description": command.description, "source": command.source,
    })).collect::<Vec<_>>() }),
    )
    .into_response()
}

#[derive(Debug, serde::Deserialize)]
struct PluginMutation {
    path: Option<PathBuf>,
    #[serde(default)]
    scope: Option<InstallScope>,
    #[serde(default)]
    allow_unlicensed: bool,
    #[serde(default)]
    agent: Option<String>,
}

