async fn list_plugins(
    State(state): State<AppState>,
    Query(query): Query<PluginScopeQuery>,
) -> axum::response::Response {
    use axum::response::IntoResponse;
    let core = scoped_core!(&state, None, query.agent.as_deref());
    let mut plugins = Vec::new();
    for scope in requested_plugin_scopes(query.scope) {
        if let Ok(items) = plugin_store(&core, scope).list() {
            let policy = core.effective_plugins();
            plugins.extend(
                items
                    .into_iter()
                    .map(|plugin| {
                        serde_json::json!({
                            "name": plugin.name,
                            "version": plugin.version,
                            "digest": plugin.digest,
                            "description": plugin.description,
                            "native_adapter": plugin.native_adapter,
                            "format": plugin.format,
                            "scope": plugin.scope,
                            "enabled": plugin.enabled,
                            "network_allowed": policy.is_network_allowed(&plugin.name),
                            "network_denied": policy.network_deny.contains(&plugin.name),
                            "network_allow": policy.network_allow,
                            "trace_id": plugin.trace_id,
                            "capabilities": plugin.capabilities,
                            "warnings": plugin.warnings,
                        })
                    })
                    .collect::<Vec<_>>(),
            );
        }
    }
    Json(serde_json::json!({ "plugins": plugins })).into_response()
}

async fn list_social_connectors(
    State(state): State<AppState>,
    axum::Extension(principal): axum::Extension<AuthenticatedPrincipal>,
    Query(query): Query<SocialAgentQuery>,
) -> axum::response::Response {
    use axum::response::IntoResponse;
    if let Err(status) = operator_only(&principal) {
        return status.into_response();
    }
    let core = scoped_core!(&state, None, query.agent.as_deref());
    let mut connectors = vak_core::social::CONNECTORS.to_vec();
    for connector in connectors.iter_mut() {
        let (name, registered) = match connector.id {
            "social-youtube" => ("YouTube", youtube_owner_preview_adapter().is_some()),
            "social-reddit" => ("Reddit", social::preview::reddit_registered()),
            "social-x" => ("X", social::preview::x_registered()),
            _ => continue,
        };
        if registered && social_plugin_enabled(&core, connector.id) {
            continue;
        }
        connector.readiness = vak_core::social::Readiness::Blocked;
        connector.reason = match name {
            "YouTube" => {
                "Install and enable the YouTube add-on to use its owner-only API search preview."
            }
            "Reddit" => {
                "Install and enable the Reddit add-on to use its owner-only search preview."
            }
            _ => "Install and enable the X add-on to use its owner-only search preview.",
        };
    }
    let connectors = connectors
        .iter()
        .map(|connector| {
            let mut value = serde_json::to_value(connector).unwrap_or_default();
            value["guidance_digest"] =
                serde_json::json!(vak_core::social::package_digest(connector.id));
            value
        })
        .collect::<Vec<_>>();
    Json(serde_json::json!({
        "connectors": connectors,
        "notice": "YouTube, Reddit and X offer owner-only search previews. LinkedIn can link an owner-visible profile identity after native PKCE setup; LinkedIn content search remains unavailable."
    }))
    .into_response()
}

fn social_plugin_enabled(core: &vak_core::Core, name: &str) -> bool {
    let Ok(workspace_plugins) = plugin_store(core, InstallScope::Workspace).list() else {
        return false;
    };
    if let Some(workspace_plugin) = workspace_plugins.iter().find(|item| item.name == name) {
        return workspace_plugin.enabled;
    }
    plugin_store(core, InstallScope::User)
        .list()
        .ok()
        .is_some_and(|items| items.iter().any(|item| item.name == name && item.enabled))
}

fn youtube_owner_preview_adapter()
-> Option<&'static vak_plugin::native_adapter::NativeAdapterRegistration> {
    vak_plugin::native_adapter::native_adapter_for_plugin("social-youtube").filter(|adapter| {
        adapter.id == "youtube-data-api-v3"
            && adapter.availability == vak_plugin::native_adapter::AdapterAvailability::OwnerPreview
            && adapter.executor
                == vak_plugin::native_adapter::CompiledExecutor::YoutubeOwnerSearchPreview
            && adapter.auth == vak_plugin::native_adapter::AdapterAuth::ApiKey
            && adapter.api_host == "www.googleapis.com"
    })
}

