    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    #[allow(clippy::disallowed_macros)]
    async fn human_feedback_produces_new_candidate_without_workspace_write() {
        vak_config::paths::isolate_home_for_tests();
        let dir = tempfile::tempdir().unwrap();
        let core = Core::new_with_trust(dir.path().to_path_buf(), true).unwrap();
        core.set_shared_scope(vak_config::scope::SharedScope::new(dir.path().join("home")));
        core.set_permission_mode(vak_config::PermissionMode::FullAccess);
        core.set_route("revision-test".into(), "test-model".into());
        let worker = std::env::current_exe()
            .unwrap()
            .parent()
            .unwrap()
            .parent()
            .unwrap()
            .join("vak-tool-worker");
        if !worker.is_file() {
            eprintln!("build vak-tool-worker to exercise this broker integration test");
            return;
        }
        core.set_tool_worker_exe(worker);
        core.set_provider_instance(Arc::new(RevisionProvider {
            capacity_key: capacity_key(),
            replies: Mutex::new(VecDeque::from(vec![
                revision_message(
                    vec![ContentBlock::ToolUse {
                        id: "edit-version-two".into(),
                        name: "write".into(),
                        input: serde_json::json!({"path": "result.txt", "content": "version two"}),
                    }],
                    StopReason::ToolUse,
                ),
                revision_message(
                    vec![ContentBlock::text("Prepared the revised draft for review.")],
                    StopReason::EndTurn,
                ),
            ])),
        }));
        seed_bound_result(&core, "session-1", "exec-1");
        let state = AppState::new(core.clone());
        let scratch = exec_dir(dir.path(), ".vak/scratch/e1");
        tokio::fs::create_dir_all(&scratch).await.unwrap();
        tokio::fs::write(scratch.join("result.txt"), "version one")
            .await
            .unwrap();
        let first = export_candidate(&state).await;
        let parent_log = find_session_on_disk(&core, "session-1").unwrap();
        register_handle(
            &state,
            "session-1".into(),
            parent_log,
            core.cwd().to_path_buf(),
            core.clone(),
        );

        let (artifact_id, first_version) =
            proposed_version(&state, &first.candidate.candidate_id, "result.txt");
        let commented = library::add_comment(
            State(state.clone()),
            Path((artifact_id.clone(), first_version.clone())),
            axum::Extension(AuthenticatedPrincipal::Operator),
            Json(library::NewComment {
                text: "Replace the text with version two".into(),
                ..Default::default()
            }),
        )
        .await;
        assert_eq!(commented.status(), StatusCode::CREATED);
        let comment_id = serde_json::from_slice::<serde_json::Value>(
            &axum::body::to_bytes(commented.into_body(), 64 * 1024)
                .await
                .unwrap(),
        )
        .unwrap()["comment_id"]
            .as_str()
            .unwrap()
            .to_string();
        let response = library::revise(
            State(state.clone()),
            Path((artifact_id.clone(), comment_id.clone())),
            axum::Extension(AuthenticatedPrincipal::Operator),
        )
        .await;
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let newer = tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                let records =
                    crate::sandbox_records::load(&sandbox_records_path(&state, "session-1"))
                        .unwrap();
                if let Some(record) = records.iter().rev().find_map(|record| match record {
                    vak_sandbox::DurableRecord::Candidate(candidate)
                        if candidate.parent_candidate_id.as_deref()
                            == Some(first.candidate.candidate_id.as_str()) =>
                    {
                        Some(candidate.clone())
                    }
                    _ => None,
                }) {
                    break record;
                }
                if let Some(failed) = records.iter().rev().find_map(|record| match record {
                    vak_sandbox::DurableRecord::CandidateRevision(revision)
                        if revision.comment_id == comment_id
                            && revision.status == vak_sandbox::CandidateRevisionStatus::Failed =>
                    {
                        Some(revision.clone())
                    }
                    _ => None,
                }) {
                    panic!("revision failed: {:?}", failed.detail);
                }
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(
            tokio::fs::read_to_string(newer.candidate.source_root.join("result.txt"))
                .await
                .unwrap(),
            "version two"
        );
        assert_eq!(
            newer.candidate.files[0].base_hash,
            first.candidate.files[0].base_hash
        );
        assert!(
            !dir.path().join("result.txt").exists(),
            "revision must not touch the original workspace"
        );
        assert!(newer.revision_session_id.is_some());
        // The revision is a version made from the one commented on.
        let revised = tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                let artifact = core.artifacts().get(&artifact_id).unwrap();
                if let Some(version) = artifact
                    .versions
                    .iter()
                    .find(|version| version.proposed_by(&newer.candidate.candidate_id))
                {
                    break version.clone();
                }
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(
            revised.parent.map(|parent| parent.to_string()),
            Some(first_version)
        );
        let accepted = promote_sandbox_candidate(
            State(state.clone()),
            Path("session-1".into()),
            Json(SandboxPromotionBody {
                candidate_id: newer.candidate.candidate_id,
                files: vec!["result.txt".into()],
            }),
        )
        .await;
        assert_eq!(accepted.status(), StatusCode::OK);
        assert_eq!(
            tokio::fs::read_to_string(dir.path().join("result.txt"))
                .await
                .unwrap(),
            "version two"
        );
    }

    /// A revision of an Office draft edits it with `office_apply`, which
    /// writes a draft under the task copy's `.vak/scratch/` and never the
    /// file itself. That draft is the next version of the same draft: the
    /// revision used to fail with "revision did not change candidate files".
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn office_revision_is_the_next_version_of_the_draft() {
        use sha2::Digest as _;
        vak_config::paths::isolate_home_for_tests();
        let dir = tempfile::tempdir().unwrap();
        let core = Core::new_with_trust(dir.path().to_path_buf(), true).unwrap();
        core.set_shared_scope(vak_config::scope::SharedScope::new(dir.path().join("home")));
        core.set_route("revision-test".into(), "test-model".into());
        pin_test_tool_worker(&core);
        let version_one = vak_ooxml::fixtures::docx();
        let digest: String = sha2::Sha256::digest(&version_one)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect();
        core.set_provider_instance(Arc::new(RevisionProvider {
            capacity_key: capacity_key(),
            replies: Mutex::new(VecDeque::from(vec![
                revision_message(
                    vec![ContentBlock::ToolUse {
                        id: "office-version-two".into(),
                        name: "office_apply".into(),
                        input: serde_json::json!({
                            "path": "letter.docx",
                            "base_digest": digest,
                            "ops": [{"op": "replace_paragraph_text", "anchor": "p@1", "text": "Annual Report"}],
                        }),
                    }],
                    StopReason::ToolUse,
                ),
                revision_message(
                    vec![ContentBlock::text("Retitled the letter.")],
                    StopReason::EndTurn,
                ),
            ])),
        }));
        seed_bound_result(&core, "session-1", "exec-1");
        let state = AppState::new(core.clone());
        tokio::fs::write(dir.path().join("letter.docx"), &version_one)
            .await
            .unwrap();
        let scratch = exec_dir(dir.path(), ".vak/scratch/e1");
        tokio::fs::create_dir_all(&scratch).await.unwrap();
        tokio::fs::write(scratch.join("letter.docx"), &version_one)
            .await
            .unwrap();
        let first = export_candidate(&state).await;
        let parent_log = find_session_on_disk(&core, "session-1").unwrap();
        register_handle(
            &state,
            "session-1".into(),
            parent_log,
            core.cwd().to_path_buf(),
            core.clone(),
        );

        let response = dispatch_candidate_revision(
            state.clone(),
            first.clone(),
            "comment-1".into(),
            "Retitle the letter".into(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let newer = tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                let records =
                    crate::sandbox_records::load(&sandbox_records_path(&state, "session-1"))
                        .unwrap();
                if let Some(failed) = records.iter().rev().find_map(|record| match record {
                    vak_sandbox::DurableRecord::CandidateRevision(revision)
                        if revision.status == vak_sandbox::CandidateRevisionStatus::Failed =>
                    {
                        Some(revision.clone())
                    }
                    _ => None,
                }) {
                    panic!("revision failed: {:?}", failed.detail);
                }
                if let Some(record) = records.iter().rev().find_map(|record| match record {
                    vak_sandbox::DurableRecord::Candidate(candidate)
                        if candidate.parent_candidate_id.as_deref()
                            == Some(first.candidate.candidate_id.as_str()) =>
                    {
                        Some(candidate.clone())
                    }
                    _ => None,
                }) {
                    break record;
                }
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        })
        .await
        .unwrap();

        let files: Vec<&str> = newer
            .candidate
            .files
            .iter()
            .map(|file| file.path.as_str())
            .collect();
        assert_eq!(files, ["letter.docx"]);
        assert_eq!(
            newer.candidate.files[0].base_hash,
            first.candidate.files[0].base_hash
        );
        let version_two = std::fs::read(newer.candidate.source_root.join("letter.docx")).unwrap();
        let mut package = vak_ooxml::Package::open(
            std::io::Cursor::new(version_two),
            vak_ooxml::Limits::default(),
        )
        .unwrap();
        let main = package.main_part().to_string();
        let body = String::from_utf8(package.read_part(&main).unwrap()).unwrap();
        assert!(body.contains("Annual Report"), "{body}");
        // One execution's versions are one draft: this is its version 2.
        assert_eq!(newer.execution_id, first.execution_id);
        assert_eq!(
            std::fs::read(dir.path().join("letter.docx")).unwrap(),
            version_one,
            "revision must not touch the original workspace"
        );
    }

    #[tokio::test]
    async fn owner_receives_live_comment_refresh_for_open_review() {
        use futures::StreamExt;

        vak_config::paths::isolate_home_for_tests();
        let dir = tempfile::tempdir().unwrap();
        let core = Core::new_with_trust(dir.path().to_path_buf(), true).unwrap();
        core.set_shared_scope(vak_config::scope::SharedScope::new(dir.path().join("home")));
        seed_bound_result(&core, "session-1", "exec-1");
        let state = AppState::new(core.clone());
        let path = core
            .scope()
            .into_root()
            .join("sessions")
            .join(vak_config::spaces::key(core.cwd()))
            .join("session-1");
        let session = SessionLog::open(path).unwrap();
        register_handle(
            &state,
            "session-1".into(),
            session,
            core.cwd().to_path_buf(),
            core,
        );
        let response = coworking_updates(
            State(state.clone()),
            Path("session-1".into()),
            axum::Extension(AuthenticatedPrincipal::Operator),
            axum::http::HeaderMap::new(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let mut events = response.into_body().into_data_stream();
        let heartbeat = tokio::time::timeout(std::time::Duration::from_secs(3), events.next())
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert!(
            std::str::from_utf8(&heartbeat)
                .unwrap()
                .contains("event: heartbeat")
        );
        state
            .get("session-1")
            .unwrap()
            .coworking_comments_tx
            .send(())
            .unwrap();
        let refresh = tokio::time::timeout(std::time::Duration::from_secs(3), events.next())
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert!(
            std::str::from_utf8(&refresh)
                .unwrap()
                .contains("event: refresh")
        );
    }

