    fn participant_of(conversation: &str) -> coworking::VerifiedPrincipal {
        coworking::VerifiedPrincipal {
            conversation_id: conversation.into(),
            audience_id: format!("conversation:{conversation}"),
            ..participant(&["read", "comment"])
        }
    }

    fn participant(capabilities: &[&str]) -> coworking::VerifiedPrincipal {
        coworking::VerifiedPrincipal {
            grant_id: "grant-1".into(),
            principal_id: "person-2".into(),
            display_name: "Asha".into(),
            conversation_id: "session-1".into(),
            audience_id: "conversation:session-1".into(),
            capabilities: capabilities.iter().map(|value| (*value).into()).collect(),
        }
    }

    #[test]
    fn participant_read_scope_is_exact_and_fail_closed() {
        let principal = participant(&["read"]);
        assert!(participant_matches_conversation_audience(
            &principal,
            "session-1",
            Some("conversation:session-1")
        ));
        assert!(!participant_matches_conversation_audience(
            &principal,
            "session-1",
            Some("conversation:other")
        ));
        assert!(!participant_matches_conversation_audience(
            &principal,
            "session-1",
            None
        ));
        assert!(!participant_matches_conversation_audience(
            &principal,
            "session-2",
            Some("conversation:session-1")
        ));
        for path in [
            "/sessions/session-1/transcript",
            "/sessions/session-1/transcript.md",
            "/sessions/session-1/presentation",
            "/sessions/session-1/results/result-1",
            "/sessions/session-1/sandbox/records",
            "/library/art-1/versions/ver-1/text",
            "/library/art-1/versions/ver-1/raw",
            "/library/art-1/versions/ver-1/document",
            "/library/art-1/versions/ver-1/review",
            "/library/art-1/versions/ver-1/comments",
            "/sessions/session-1/coworking/updates",
            "/sessions/session-1/coworking/presence",
            "/sessions/session-1/office-workspaces",
        ] {
            assert!(participant_read_route_allowed(
                &axum::http::Method::GET,
                path,
                &principal
            ));
        }
        for path in [
            "/sessions/session-2/transcript",
            "/sessions/session-1/events",
            "/sessions/session-1/run",
            "/sessions/session-1/sandbox/executions",
            "/sessions/session-1/sandbox/promote",
            "/sessions/session-1/sandbox/candidates/candidate-1/comments",
            "/sessions/session-1/sandbox/candidates/candidate-1/files",
            "/sessions/session-1/sandbox/candidates/candidate-1/office",
            "/library/art-1/versions/ver-1/save",
            "/library",
            "/library/art-1",
            "/library/art-1/versions/ver-1",
            "/fs/file",
            "/fs/office",
            "/config",
        ] {
            assert!(!participant_read_route_allowed(
                &axum::http::Method::GET,
                path,
                &principal
            ));
        }
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/library/art-1/versions/ver-1/comments",
            &principal
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/library/art-1/versions/ver-1/comments",
            &participant(&["read", "comment"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/sandbox/candidates/candidate-1/comments",
            &participant(&["read", "comment"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/coworking/messages",
            &participant(&["read", "message"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/office-workspaces/room-1/presence",
            &participant(&["read"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/office-workspaces/room-1",
            &participant(&["read"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/office-workspaces/room-1",
            &participant(&["read", "edit"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/coworking/messages",
            &participant(&["read", "comment"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::GET,
            "/sessions/session-1/coworking/approvals",
            &participant(&["read", "approve_once"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/coworking/approvals/request-1",
            &participant(&["read"])
        ));
        assert!(participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/coworking/approvals/request-1",
            &participant(&["read", "message"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/sessions/session-1/sandbox/promote",
            &participant(&["read", "comment"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::POST,
            "/library/art-1/comments/cmt-1/revise",
            &participant(&["read", "comment"])
        ));
        assert!(!participant_read_route_allowed(
            &axum::http::Method::GET,
            "/sessions/session-1/transcript",
            &participant(&["comment"])
        ));
    }

